import React from 'react';
import { AbsoluteFill, Easing, interpolate } from 'remotion';
import { useS, en, clamp, DUR, Carita, Ondas, Fondo, FONT } from './kit';

const W = 1080;
const H = 1920;

const DIFICIL = en('difícil');
const GARGANTA = en('garganta');
const PENSAMIENTOS = en('pensamientos');
const PALABRAS_C = en('palabras', 2);
const PAZ = en('paz');
const SOLO = en('solo');
const TRECE = en('trece');
const CAMINO = en('camino');
const SABIDURIA = en('sabiduría');
const TERRENO = en('terreno');
const AMEN = en('amén');

const Cielo: React.FC<{ s: number }> = ({ s }) => {
  const t = interpolate(s, [PAZ, TRECE, AMEN], [0, 0.6, 1], clamp);
  const c1 = interpolate(t, [0, 0.5, 1], [20, 40, 70]); // R
  const c2 = interpolate(t, [0, 0.5, 1], [30, 60, 110]); // G
  const c3 = interpolate(t, [0, 0.5, 1], [60, 100, 180]); // B
  return (
    <AbsoluteFill style={{ 
      background: `linear-gradient(180deg, rgb(${c1},${c2},${c3}) 0%, rgb(${c1 + 20},${c2 + 20},${c3 + 20}) 100%)` 
    }} />
  );
};

const Camino: React.FC<{ s: number }> = ({ s }) => {
  const progreso = interpolate(s, [0, DUR], [0, 1], clamp);
  const luz = interpolate(s, [TERRENO, AMEN], [0.3, 1], clamp);
  return (
    <svg width={W} height={800} style={{ position: 'absolute', bottom: 0, left: 0 }} viewBox="0 0 1080 800">
      <path 
        d="M 540 0 L 0 800 L 1080 800 Z" 
        fill={`rgb(${40 + 60 * luz}, ${35 + 50 * luz}, ${60 + 30 * luz})`} 
        opacity={0.8}
      />
      <path 
        d="M 540 0 L 520 800 L 560 800 Z" 
        fill="#ffd84d" 
        opacity={0.4 + 0.6 * luz} 
        style={{ transform: `scaleY(${progreso})`, transformOrigin: 'top' }}
      />
    </svg>
  );
};

const Nudo: React.FC<{ s: number }> = ({ s }) => {
  const vis = interpolate(s, [GARGANTA - 0.5, GARGANTA, PENSAMIENTOS + 1], [0, 1, 0], clamp);
  if (vis <= 0) return null;
  return (
    <div style={{ 
      position: 'absolute', left: 540, top: 1100, 
      width: 300, height: 300, borderRadius: '50%',
      background: 'radial-gradient(circle, rgba(0,0,0,0.4) 0%, transparent 70%)',
      transform: `translate(-50%, -50%) scale(${1 + 0.2 * Math.sin(s * 5)})`,
      opacity: vis
    }} />
  );
};

const ParticulasPalabras: React.FC<{ s: number }> = ({ s }) => {
  const activa = s > PALABRAS_C && s < AMEN;
  if (!activa) return null;
  return (
    <AbsoluteFill>
      {Array.from({ length: 12 }).map((_, i) => {
        const t0 = PALABRAS_C + i * 0.2;
        const p = interpolate(s, [t0, t0 + 2], [0, 1], clamp);
        if (p <= 0 || p >= 1) return null;
        return (
          <div key={i} style={{
            position: 'absolute',
            left: 540 + Math.sin(i * 1.5 + s) * 200 * p,
            top: 1000 - p * 600,
            width: 15, height: 15, borderRadius: '50%',
            background: '#fffbe0',
            boxShadow: '0 0 15px #ffd84d',
            opacity: 1 - p
          }} />
        );
      })}
    </AbsoluteFill>
  );
};

const Aura: React.FC<{ s: number }> = ({ s }) => {
  const v = interpolate(s, [TRECE, AMEN], [0, 1], clamp);
  return (
    <div style={{
      position: 'absolute', left: 540, top: 1120,
      width: 600, height: 600, borderRadius: '50%',
      background: 'radial-gradient(circle, rgba(255,216,77,0.2) 0%, transparent 70%)',
      transform: `translate(-50%, -50%) scale(${1 + 0.1 * Math.sin(s * 2)})`,
      opacity: v
    }} />
  );
};

export const Escena: React.FC = () => {
  const { s, spr } = useS();

  const zoom = interpolate(s, [0, DUR], [1, 1.15], clamp);
  const boca = s > GARGANTA && s < PENSAMIENTOS + 1 ? 'o' : 'feliz';
  const saltos = [DIFICIL, PAZ, TRECE, AMEN];

  return (
    <AbsoluteFill style={{ backgroundColor: '#05081a', overflow: 'hidden' }}>
      <Cielo s={s} />

      <AbsoluteFill style={{ transform: `scale(${zoom})`, transformOrigin: 'center 80%' }}>
        <Camino s={s} />

        <Aura s={s} />

        <Carita 
          x={540} 
          y={1120} 
          size={420} 
          boca={boca}
          saltos={saltos}
          color={['#fffbe0', '#ffd84d', '#e6b800']}
        />

        <Nudo s={s} />
        <ParticulasPalabras s={s} />

        <Ondas x={540} y={1120} t0={PAZ} color="#ffd84d" radio={500} />
        <Ondas x={540} y={1120} t0={TRECE} color="#ffffff" radio={600} />
      </AbsoluteFill>

      {/* Partículas de ambiente */}
      {Array.from({ length: 20 }).map((_, i) => {
        const x = (i * 197) % W;
        const y = H - ((i * 311 + s * 50) % (H + 100));
        return (
          <div key={i} style={{
            position: 'absolute', left: x, top: y,
            width: 4, height: 4, borderRadius: 2,
            background: '#fff', opacity: 0.2
          }} />
        );
      })}

      {/* Viñeta suave */}
      <AbsoluteFill style={{ 
        background: 'radial-gradient(circle, transparent 40%, rgba(0,0,0,0.4) 100%)',
        pointerEvents: 'none'
      }} />
    </AbsoluteFill>
  );
};
